import React from "react";

export default function AssignmentResult({ assignedVehicles }) {
  if (!Array.isArray(assignedVehicles) || assignedVehicles.length === 0) return null;

  return (
    <div className="results-box">
      <h2>Assignment Results</h2>
      {assignedVehicles.map((veh, vi) => (
        <div className="vehicle-result" key={vi}>
          <h3>
            Vehicle: {veh.truckId} &nbsp;— Type: {veh.type} · Capacity: {veh.capacity}kg
          </h3>
          <p><strong>Current Load:</strong> {veh.currentLoad}kg</p>
          <div className="assigned-customers">
            <strong>Assigned Customers:</strong>
            <ul>
              {veh.assignedCustomers?.map((ac, ai) => (
                <li key={ai}>
                  {ac.customerName} ({ac.customerName}) – {ac.loadWeight}kg
                </li>
              ))}
            </ul>
          </div>
          <div className="route-list">
            <strong>Route:</strong>
            <ol>
              {veh.route?.map((step, si) => {
                if (step[0] === "start") {
                  return (
                    <li key={si}>Start at ({step[1].toFixed(4)}, {step[2].toFixed(4)})</li>
                  );
                } else if (step[0] === "storage") {
                  return (
                    <li key={si}>Pick up at Storage {step[1]} (lat: {step[2].toFixed(4)}, lng: {step[3].toFixed(4)})</li>
                  );
                } else if (step[0] === "customer") {
                  return (
                    <li key={si}>Deliver to Customer {step[1]} (lat: {step[2].toFixed(4)}, lng: {step[3].toFixed(4)})</li>
                  );
                } else {
                  return <li key={si}>{JSON.stringify(step)}</li>;
                }
              })}
            </ol>
          </div>
          <hr />
        </div>
      ))}
    </div>
  );
}
